export const PERSONALITY_SVGS = {
  "legend": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"レジェンド\">\n  <defs>\n    <clipPath id=\"legend-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"legend-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"legend-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"legend-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#FFB526\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"legend-glow\">\n      <stop offset=\"0%\" stop-color=\"#FFB627\" stop-opacity=\"0.35\"/>\n      <stop offset=\"60%\" stop-color=\"#FFB627\" stop-opacity=\"0\"/>\n      <stop offset=\"100%\" stop-color=\"#FFB627\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"legend-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#FFB526\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#FFB526\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#legend-shadow)\">\n    <g clip-path=\"url(#legend-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#legend-neonTint)\"/>\n      <g id=\"legend-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('legend-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function seg(x1,y1,x2,y2){ return `M${x1} ${y1} L${x2} ${y2}`; }\n    function use(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n\n    const PAL = [\"#FFE08A\",\"#FFB627\",\"#FF7A1A\"];\n    function pal(i){ const n=PAL.length; return PAL[((i%n)+n)%n]; }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const glow = document.createElementNS(NS,'circle');\n    glow.setAttribute('cx',200); glow.setAttribute('cy',159); glow.setAttribute('fill','url(#legend-glow)');\n    art.appendChild(glow);\n\n    const ringG = g('legend-ringG');\n    art.insertBefore(use('legend-ringG','url(#legend-blur28)',0.9), ringG);\n    const ptclG = g('legend-ptclG');\n    art.insertBefore(use('legend-ptclG','url(#legend-blur16)',0.9), ptclG);\n\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const ptcls = Array.from({length:60}, () => ({\n      angle: rnd(0, Math.PI*2), radius: 78+rnd(6,50), baseR: rnd(0.4,1.8),\n      phase: rnd(0, Math.PI*2), speed: rnd(0.15,0.5), ci: Math.random()>0.7?0:1\n    }));\n    const chords = Array.from({length:7}, () => { const a=rnd(0,Math.PI*2); return {a1:a, a2:a+rnd(0.5,2.5), phase:rnd(0,Math.PI*2)}; });\n    const ticks = Array.from({length:80}, (_,i) => 3 + Math.abs(Math.sin(i*1.7))*5);\n\n    function draw(t){\n      const cx=200, cy=159, R=78, rot = t*6*Math.PI/180;\n      const glowR = 90 + Math.sin(t*1.4)*18;\n      glow.setAttribute('r', glowR);\n\n      clear(ringG);\n      for (let i=0;i<80;i++){\n        const a = i/80*Math.PI*2 + rot;\n        path(ringG, seg(cx+Math.cos(a)*R, cy+Math.sin(a)*R, cx+Math.cos(a)*(R+ticks[i]), cy+Math.sin(a)*(R+ticks[i])),\n          {stroke: hexA(pal(1),0.85), 'stroke-width':1.2, 'stroke-linecap':'round'});\n      }\n      circleEl(ringG, cx, cy, R,   {fill:'none', stroke:hexA(pal(1),0.6), 'stroke-width':1});\n      circleEl(ringG, cx, cy, R-7, {fill:'none', stroke:hexA(pal(0),0.35),'stroke-width':0.5});\n      chords.forEach(c => {\n        const a1=c.a1+rot, a2=c.a2+rot;\n        path(ringG, seg(cx+Math.cos(a1)*R, cy+Math.sin(a1)*R, cx+Math.cos(a2)*R, cy+Math.sin(a2)*R),\n          {stroke: hexA(pal(0), 0.15+0.35*Math.abs(Math.sin(t*0.8+c.phase))), 'stroke-width':0.6});\n      });\n      for (let i=0;i<5;i++){\n        const a=i/5*Math.PI*2+rot;\n        circleEl(ringG, cx+Math.cos(a)*R, cy+Math.sin(a)*R, 2+Math.abs(Math.sin(t*2+a))*1.6, {fill:pal(0)});\n      }\n\n      clear(ptclG);\n      ptcls.forEach(p=>{\n        const a = p.angle + t*p.speed*0.05;\n        circleEl(ptclG, cx+Math.cos(a)*p.radius, cy+Math.sin(a)*p.radius,\n          p.baseR*(0.4+0.6*Math.abs(Math.sin(t*1.6+p.phase))), {fill: hexA(pal(p.ci),0.6)});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "obsessed-fan": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"推しが本気\">\n  <defs>\n    <clipPath id=\"oshi-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"oshi-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"oshi-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"oshi-blur6\" x=\"-100%\" y=\"-100%\" width=\"300%\" height=\"300%\"><feGaussianBlur stdDeviation=\"6\"/></filter>\n    <filter id=\"oshi-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#FF3B6B\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"oshi-glow\">\n      <stop offset=\"0%\" stop-color=\"#FF3B6B\" stop-opacity=\"0\"/>\n      <stop offset=\"40%\" stop-color=\"#FF3B6B\" stop-opacity=\"0.18\"/>\n      <stop offset=\"100%\" stop-color=\"#FF3B6B\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"oshi-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#FF3B6B\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#FF3B6B\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#oshi-shadow)\">\n    <g clip-path=\"url(#oshi-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#oshi-neonTint)\"/>\n      <g id=\"oshi-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('oshi-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function seg(x1,y1,x2,y2){ return `M${x1} ${y1} L${x2} ${y2}`; }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n    function smooth(pts){\n      if (pts.length<2) return '';\n      let d = `M${pts[0][0]} ${pts[0][1]}`;\n      for (let i=0;i<pts.length-1;i++){ const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2; d += ` Q${pts[i][0]} ${pts[i][1]} ${mx} ${my}`; }\n      d += ` L${pts[pts.length-1][0]} ${pts[pts.length-1][1]}`;\n      return d;\n    }\n\n    const PAL = [\"#FFB3C7\",\"#FF3B6B\",\"#C71F4C\"];\n    function pal(i){ const n=PAL.length; return PAL[((i%n)+n)%n]; }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const bgGlow = document.createElementNS(NS,'ellipse');\n    bgGlow.setAttribute('cx',200); bgGlow.setAttribute('cy',165);\n    bgGlow.setAttribute('rx',280); bgGlow.setAttribute('ry',155);\n    bgGlow.setAttribute('fill','url(#oshi-glow)');\n    art.appendChild(bgGlow);\n\n    const ringG = g('oshi-ringG');\n    art.insertBefore(useEl('oshi-ringG','url(#oshi-blur16)',0.9), ringG);\n    const waveG = g('oshi-waveG');\n    art.insertBefore(useEl('oshi-waveG','url(#oshi-blur28)',0.9), waveG);\n    const wave2G = g('oshi-wave2G');\n    const spikeG = g('oshi-spikeG');\n    art.insertBefore(useEl('oshi-spikeG','url(#oshi-blur6)',0.9), spikeG);\n    const lineG = g('oshi-lineG');\n    art.insertBefore(useEl('oshi-lineG','url(#oshi-blur28)',0.9), lineG);\n    const ptclG = g('oshi-ptclG');\n    art.insertBefore(useEl('oshi-ptclG','url(#oshi-blur16)',0.9), ptclG);\n\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const ptcls = Array.from({length:40}, () => ({ angle: rnd(0,Math.PI*2), speed: rnd(20,60), phase: rnd(0,3) }));\n    const ringPhases = [0,1,2,3,4];\n\n    function draw(t){\n      const cx=200, cy=165;\n\n      clear(ringG);\n      ringPhases.forEach(ph=>{\n        const k = (((t+ph)%3)+3)%3/3;\n        circleEl(ringG, cx, cy, 5+k*110, {fill:'none', stroke:hexA(pal(1),(1-k)*0.7), 'stroke-width':1});\n      });\n\n      const pts=[], pts2=[];\n      for (let x=0;x<=400;x+=2){\n        const env = Math.exp(-Math.abs((x-cx)/cx)*4)*70;\n        pts.push([x, cy + Math.sin(x*0.35-t*12)*env*Math.cos(t*4+x*0.05)]);\n        pts2.push([x, cy + Math.sin(x*0.4-t*8+1)*env*0.6]);\n      }\n      clear(waveG);\n      path(waveG, smooth(pts), {stroke:pal(1), 'stroke-width':1.5, 'stroke-linecap':'round'});\n      clear(wave2G);\n      path(wave2G, smooth(pts2), {stroke:hexA(pal(0),0.7), 'stroke-width':0.8});\n\n      const peakH = 110 + Math.sin(t*6)*18;\n      clear(spikeG);\n      path(spikeG, `M${cx-3} ${cy} L${cx} ${cy-peakH} L${cx+3} ${cy} M${cx-3} ${cy} L${cx} ${cy+peakH*0.7} L${cx+3} ${cy}`,\n        {stroke: pal(0), 'stroke-width':2});\n\n      clear(lineG);\n      path(lineG, seg(cx,0,cx,310), {stroke: hexA(pal(0), 0.3+Math.abs(Math.sin(t*6))*0.4), 'stroke-width':1});\n\n      clear(ptclG);\n      ptcls.forEach(p=>{\n        const k = (((t*p.speed*0.02+p.phase)%1)+1)%1;\n        circleEl(ptclG, cx+Math.cos(p.angle)*k*110, cy+Math.sin(p.angle)*k*110*0.55, 0.85,\n          {fill: hexA(pal(0),(1-k)*0.9)});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "single-focus": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"一点集中型\">\n  <defs>\n    <clipPath id=\"focus-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"focus-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"focus-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"focus-blur6\" x=\"-100%\" y=\"-100%\" width=\"300%\" height=\"300%\"><feGaussianBlur stdDeviation=\"6\"/></filter>\n    <filter id=\"focus-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#21E0B5\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"focus-glow\">\n      <stop offset=\"0%\" stop-color=\"#22E1B6\" stop-opacity=\"0.5\"/>\n      <stop offset=\"65%\" stop-color=\"#22E1B6\" stop-opacity=\"0\"/>\n      <stop offset=\"100%\" stop-color=\"#22E1B6\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"focus-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#21E0B5\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#21E0B5\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#focus-shadow)\">\n    <g clip-path=\"url(#focus-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#focus-neonTint)\"/>\n      <g id=\"focus-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('focus-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function seg(x1,y1,x2,y2){ return `M${x1} ${y1} L${x2} ${y2}`; }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n    function smooth(pts){\n      if (pts.length<2) return '';\n      let d = `M${pts[0][0]} ${pts[0][1]}`;\n      for (let i=0;i<pts.length-1;i++){ const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2; d += ` Q${pts[i][0]} ${pts[i][1]} ${mx} ${my}`; }\n      d += ` L${pts[pts.length-1][0]} ${pts[pts.length-1][1]}`;\n      return d;\n    }\n\n    const PAL = [\"#9DFFE3\",\"#22E1B6\",\"#0D9B7B\"];\n    function pal(i){ const n=PAL.length; return PAL[((i%n)+n)%n]; }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const cx=200, cy=185;\n    const bgGlow = document.createElementNS(NS,'ellipse');\n    bgGlow.setAttribute('cy',cy); bgGlow.setAttribute('ry',55); bgGlow.setAttribute('fill','url(#focus-glow)');\n    art.appendChild(bgGlow);\n\n    const baseline = document.createElementNS(NS,'path');\n    baseline.setAttribute('d', seg(0,cy,400,cy));\n    baseline.setAttribute('stroke', hexA(pal(1),0.18)); baseline.setAttribute('stroke-width',0.4);\n    art.appendChild(baseline);\n\n    const barG = g('focus-barG');\n    art.insertBefore(useEl('focus-barG','url(#focus-blur28)',0.9), barG);\n    const tipG = g('focus-tipG');\n    art.insertBefore(useEl('focus-tipG','url(#focus-blur6)',0.9), tipG);\n    const ptclG = g('focus-ptclG');\n    art.insertBefore(useEl('focus-ptclG','url(#focus-blur16)',0.9), ptclG);\n\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const bars = Array.from({length:72}, (_,i)=>{ const x=i/71*400; const dx=(x-cx)/cx; return {x, env: Math.exp(-dx*dx*7), phase: rnd(0,Math.PI*2)}; });\n    const ptcls = Array.from({length:22}, ()=>({ x: 200+rnd(-90,90), y: 175-rnd(15,95), phase: rnd(0,Math.PI*2) }));\n\n    function draw(t){\n      bgGlow.setAttribute('cx', cx); bgGlow.setAttribute('rx', 100+Math.sin(t*3)*16);\n\n      clear(barG);\n      const tips = [];\n      bars.forEach(b=>{\n        const hUp = b.env*(75+Math.sin(t*8+b.phase)*55) + b.env*22;\n        path(barG, seg(b.x, cy-Math.max(2,hUp), b.x, cy+Math.max(1,hUp*0.42)),\n          {stroke: hexA(pal(1), 0.5+b.env*0.5), 'stroke-width':1.5, 'stroke-linecap':'round'});\n        tips.push([b.x, cy-hUp]);\n      });\n\n      clear(tipG);\n      path(tipG, smooth(tips), {stroke: hexA(pal(0),0.85), 'stroke-width':1.2});\n\n      clear(ptclG);\n      ptcls.forEach(p=>{\n        circleEl(ptclG, p.x, p.y+Math.sin(t*1.6+p.phase)*6, 1.1,\n          {fill: hexA(pal(0), 0.3+Math.abs(Math.sin(t*2+p.phase))*0.5)});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "heavy-rotator": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"ヘビロテ職人\">\n  <defs>\n    <clipPath id=\"heavy-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"heavy-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"heavy-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"heavy-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#B366FF\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"heavy-glow\">\n      <stop offset=\"0%\" stop-color=\"#B265FF\" stop-opacity=\"0\"/>\n      <stop offset=\"55%\" stop-color=\"#B265FF\" stop-opacity=\"0.18\"/>\n      <stop offset=\"75%\" stop-color=\"#B265FF\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"heavy-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#B366FF\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#B366FF\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#heavy-shadow)\">\n    <g clip-path=\"url(#heavy-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#heavy-neonTint)\"/>\n      <g id=\"heavy-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('heavy-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function seg(x1,y1,x2,y2){ return `M${x1} ${y1} L${x2} ${y2}`; }\n    function poly(pts, closed){ if(!pts.length) return ''; let d=`M${pts[0][0]} ${pts[0][1]}`; for(let i=1;i<pts.length;i++) d+=` L${pts[i][0]} ${pts[i][1]}`; if(closed) d+=' Z'; return d; }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n\n    const PAL = [\"#E6B8FF\",\"#B265FF\",\"#7A2BD4\"];\n    function pal(i){ const n=PAL.length; return PAL[((i%n)+n)%n]; }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const cx=200, cy=160, R=80;\n    const bgGlow = document.createElementNS(NS,'circle');\n    bgGlow.setAttribute('cx',cx); bgGlow.setAttribute('cy',cy); bgGlow.setAttribute('r',110);\n    bgGlow.setAttribute('fill','url(#heavy-glow)');\n    art.appendChild(bgGlow);\n\n    const outerG = g('heavy-outerG');\n    art.insertBefore(useEl('heavy-outerG','url(#heavy-blur28)',0.9), outerG);\n    const innerPath = document.createElementNS(NS,'path');\n    innerPath.setAttribute('fill','none'); innerPath.setAttribute('stroke', hexA(pal(0),0.7)); innerPath.setAttribute('stroke-width',0.8);\n    art.appendChild(innerPath);\n    const baseCircle = document.createElementNS(NS,'circle');\n    baseCircle.setAttribute('cx',cx); baseCircle.setAttribute('cy',cy); baseCircle.setAttribute('r',R);\n    baseCircle.setAttribute('fill','none'); baseCircle.setAttribute('stroke', hexA(pal(0),0.35)); baseCircle.setAttribute('stroke-width',0.4);\n    art.appendChild(baseCircle);\n    const spikeG = g('heavy-spikeG');\n    art.insertBefore(useEl('heavy-spikeG','url(#heavy-blur16)',0.9), spikeG);\n\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const ptcls = Array.from({length:80}, ()=>({ angle: rnd(0,Math.PI*2), radius: 80+rnd(-10,40), baseR: rnd(0.4,1.5), phase: rnd(0,Math.PI*2), speed: rnd(0.1,0.3), ci: Math.random()>0.5?0:1 }));\n    const seeds = Array.from({length:36}, ()=>Math.random());\n\n    function draw(t){\n      const outer=[], inner=[];\n      for (let i=0;i<=96;i++){\n        const a = i/96*Math.PI*2;\n        const n = Math.sin(a*7+t*1.5)*4 + Math.sin(a*13+t*2.2)*3 + Math.sin(a*23+t*1.1)*2.2;\n        outer.push([cx+Math.cos(a)*(R+n), cy+Math.sin(a)*(R+n)]);\n        inner.push([cx+Math.cos(a)*(R+n-7), cy+Math.sin(a)*(R+n-7)]);\n      }\n      clear(outerG);\n      path(outerG, poly(outer,true), {stroke: pal(1), 'stroke-width':1.6, 'stroke-linecap':'round'});\n      innerPath.setAttribute('d', poly(inner,true));\n\n      clear(spikeG);\n      seeds.forEach((seed,idx)=>{\n        const a = idx/36*Math.PI*2;\n        const h = 4 + Math.abs(Math.sin(t*3+seed*10))*12;\n        path(spikeG, seg(cx+Math.cos(a)*R, cy+Math.sin(a)*R, cx+Math.cos(a)*(R+h), cy+Math.sin(a)*(R+h)),\n          {stroke: hexA(pal(0), 0.2+Math.abs(Math.sin(t*2+seed*7))*0.6), 'stroke-width':0.7, 'stroke-linecap':'round'});\n      });\n      ptcls.forEach(p=>{\n        const a = p.angle + t*p.speed*0.04;\n        circleEl(spikeG, cx+Math.cos(a)*p.radius, cy+Math.sin(a)*p.radius,\n          p.baseR*(0.5+0.5*Math.abs(Math.sin(t*2+p.phase))), {fill: hexA(pal(p.ci),0.6)});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "explorer": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"音楽探検家\">\n  <defs>\n    <clipPath id=\"expl-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"expl-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"expl-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"expl-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#5CB8FF\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"expl-glow\">\n      <stop offset=\"0%\" stop-color=\"#A06BFF\" stop-opacity=\"0.35\"/>\n      <stop offset=\"70%\" stop-color=\"#FF6BD2\" stop-opacity=\"0.05\"/>\n      <stop offset=\"100%\" stop-color=\"#FF6BD2\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"expl-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#5CB8FF\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#5CB8FF\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#expl-shadow)\">\n    <g clip-path=\"url(#expl-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#expl-neonTint)\"/>\n      <g id=\"expl-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('expl-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n    function smooth(pts){\n      if (pts.length<2) return '';\n      let d = `M${pts[0][0]} ${pts[0][1]}`;\n      for (let i=0;i<pts.length-1;i++){ const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2; d += ` Q${pts[i][0]} ${pts[i][1]} ${mx} ${my}`; }\n      d += ` L${pts[pts.length-1][0]} ${pts[pts.length-1][1]}`;\n      return d;\n    }\n\n    const PAL = [\"#7AE0FF\",\"#A06BFF\",\"#FF6BD2\"];\n    function pal(i){ const n=PAL.length; return PAL[((i%n)+n)%n]; }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const cx=200, cy=165;\n    const bgGlow = document.createElementNS(NS,'circle');\n    bgGlow.setAttribute('cx',cx); bgGlow.setAttribute('cy',cy); bgGlow.setAttribute('r',280);\n    bgGlow.setAttribute('fill','url(#expl-glow)');\n    art.appendChild(bgGlow);\n\n    const streamG = g('expl-streamG');\n    art.insertBefore(useEl('expl-streamG','url(#expl-blur28)',0.9), streamG);\n    const ptclG = g('expl-ptclG');\n    art.insertBefore(useEl('expl-ptclG','url(#expl-blur16)',0.9), ptclG);\n\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const angles = [-0.45,-0.18,0.05,0.25,0.5];\n    const streams = angles.map((a,i)=>({angle:a, ci:i%3, phase:i}));\n    const ptcls = Array.from({length:130}, ()=>({ x0: rnd(0,400), y0: rnd(0,310), vx: rnd(-30,30), vy: rnd(-15,15), baseR: rnd(0.4,2.0), phase: rnd(0,Math.PI*2), life: rnd(2,6), t0: rnd(0,4), ci: Math.floor(rnd(0,3)) }));\n\n    function draw(t){\n      clear(streamG);\n      streams.forEach(s=>{\n        const pts = [];\n        for (let x=-20;x<=420;x+=6){\n          const baseY = cy + (x-cx)/100*50*Math.tan(s.angle);\n          pts.push([x, baseY+Math.sin(x*0.04+t*1.5+s.phase)*24+Math.sin(x*0.09+t*2+s.phase)*10]);\n        }\n        path(streamG, smooth(pts), {stroke: hexA(pal(s.ci),0.85), 'stroke-width':1.4, 'stroke-linecap':'round'});\n      });\n\n      clear(ptclG);\n      ptcls.forEach(p=>{\n        const local = (((t+p.t0)%p.life)+p.life)%p.life / p.life;\n        const op = Math.sin(local*Math.PI)*0.85;\n        circleEl(ptclG, p.x0+p.vx*local*2, p.y0+p.vy*local*2+Math.sin(t*1.2+p.phase)*4,\n          Math.max(0.1, p.baseR*(0.5+0.5*Math.sin(local*Math.PI))), {fill: hexA(pal(p.ci),Math.max(0,op))});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "loyal-listener": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"固定リスナー\">\n  <defs>\n    <clipPath id=\"loyal-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"loyal-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"loyal-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"loyal-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#4A8CFF\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"loyal-glow\">\n      <stop offset=\"0%\" stop-color=\"#4A8BFF\" stop-opacity=\"0\"/>\n      <stop offset=\"40%\" stop-color=\"#4A8BFF\" stop-opacity=\"0.18\"/>\n      <stop offset=\"100%\" stop-color=\"#4A8BFF\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"loyal-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#4A8CFF\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#4A8CFF\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#loyal-shadow)\">\n    <g clip-path=\"url(#loyal-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#loyal-neonTint)\"/>\n      <g id=\"loyal-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('loyal-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function seg(x1,y1,x2,y2){ return `M${x1} ${y1} L${x2} ${y2}`; }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n    function smooth(pts){\n      if (pts.length<2) return '';\n      let d = `M${pts[0][0]} ${pts[0][1]}`;\n      for (let i=0;i<pts.length-1;i++){ const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2; d += ` Q${pts[i][0]} ${pts[i][1]} ${mx} ${my}`; }\n      d += ` L${pts[pts.length-1][0]} ${pts[pts.length-1][1]}`;\n      return d;\n    }\n\n    const PAL = [\"#8FB8FF\",\"#4A8BFF\",\"#1D58D9\"];\n    function pal(i){ const n=PAL.length; return PAL[((i%n)+n)%n]; }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const cx=200, cy=170;\n    const bgGlow = document.createElementNS(NS,'circle');\n    bgGlow.setAttribute('cx',cx); bgGlow.setAttribute('cy',cy); bgGlow.setAttribute('r',150);\n    bgGlow.setAttribute('fill','url(#loyal-glow)');\n    art.appendChild(bgGlow);\n\n    const gridG = g('loyal-gridG');\n    for (let i=0;i<30;i++){\n      const x = i/29*DW, env = 1-Math.abs((x-cx)/cx)*0.6;\n      path(gridG, seg(x,cy-50*env,x,cy+50*env), {stroke: hexA(pal(1),0.18*env), 'stroke-width':0.4});\n    }\n\n    const layerG = g('loyal-layerG');\n    const mainG = g('loyal-mainG');\n    art.insertBefore(useEl('loyal-mainG','url(#loyal-blur28)',0.9), mainG);\n    const shiftPath = document.createElementNS(NS,'path');\n    shiftPath.setAttribute('fill','none'); shiftPath.setAttribute('stroke', hexA(pal(0),0.7)); shiftPath.setAttribute('stroke-width',0.8);\n    art.appendChild(shiftPath);\n    const dotG = g('loyal-dotG');\n    art.insertBefore(useEl('loyal-dotG','url(#loyal-blur16)',0.9), dotG);\n\n    const offsets = Array.from({length:14}, (_,i)=>i/14);\n\n    function waveY(x, t, phaseOffset){\n      const env = (1-Math.abs((x-cx)/cx))*0.85+0.15;\n      return cy + Math.sin(x*0.06 - t*1.6 + (phaseOffset||0))*30*env;\n    }\n\n    function draw(t){\n      clear(layerG);\n      for (let i=0;i<3;i++){\n        const pts=[];\n        for (let x=0;x<=DW;x+=4) pts.push([x, waveY(x,t,i*0.4)]);\n        path(layerG, smooth(pts), {stroke: hexA(pal(0), 0.18+i*0.06), 'stroke-width':1});\n      }\n\n      const pts=[];\n      for (let x=0;x<=DW;x+=3) pts.push([x, waveY(x,t,0)]);\n      clear(mainG);\n      path(mainG, smooth(pts), {stroke: pal(1), 'stroke-width':1.8, 'stroke-linecap':'round'});\n      shiftPath.setAttribute('d', smooth(pts.map(p=>[p[0], p[1]-0.5])));\n\n      clear(dotG);\n      offsets.forEach(ox=>{\n        const x = (((ox+t*0.05)%1)+1)%1 * DW;\n        circleEl(dotG, x, waveY(x,t,0), 1.3, {fill: pal(0)});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "growing-listener": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"成長型リスナー\">\n  <defs>\n    <clipPath id=\"growth-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"growth-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"growth-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"growth-blur6\" x=\"-100%\" y=\"-100%\" width=\"300%\" height=\"300%\"><feGaussianBlur stdDeviation=\"6\"/></filter>\n    <filter id=\"growth-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#33E08F\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"growth-glow\">\n      <stop offset=\"0%\" stop-color=\"#33E08E\" stop-opacity=\"0\"/>\n      <stop offset=\"40%\" stop-color=\"#33E08E\" stop-opacity=\"0.18\"/>\n      <stop offset=\"100%\" stop-color=\"#33E08E\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"growth-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#33E08F\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#33E08F\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#growth-shadow)\">\n    <g clip-path=\"url(#growth-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#growth-neonTint)\"/>\n      <g id=\"growth-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('growth-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function seg(x1,y1,x2,y2){ return `M${x1} ${y1} L${x2} ${y2}`; }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n    function smooth(pts){\n      if (pts.length<2) return '';\n      let d = `M${pts[0][0]} ${pts[0][1]}`;\n      for (let i=0;i<pts.length-1;i++){ const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2; d += ` Q${pts[i][0]} ${pts[i][1]} ${mx} ${my}`; }\n      d += ` L${pts[pts.length-1][0]} ${pts[pts.length-1][1]}`;\n      return d;\n    }\n\n    const PAL = [\"#A0FFD0\",\"#33E08E\",\"#0F9A5A\"];\n    function pal(i){ const n=PAL.length; return PAL[((i%n)+n)%n]; }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const bgGlow = document.createElementNS(NS,'circle');\n    bgGlow.setAttribute('cx',200); bgGlow.setAttribute('cy',155); bgGlow.setAttribute('r',150);\n    bgGlow.setAttribute('fill','url(#growth-glow)');\n    art.appendChild(bgGlow);\n\n    const barG = g('growth-barG');\n    art.insertBefore(useEl('growth-barG','url(#growth-blur16)',0.9), barG);\n    const curveG = g('growth-curveG');\n    art.insertBefore(useEl('growth-curveG','url(#growth-blur28)',0.9), curveG);\n    const shiftPath = document.createElementNS(NS,'path');\n    shiftPath.setAttribute('fill','none'); shiftPath.setAttribute('stroke', hexA(pal(0),0.8)); shiftPath.setAttribute('stroke-width',0.8);\n    art.appendChild(shiftPath);\n    const headG = g('growth-headG');\n    art.insertBefore(useEl('growth-headG','url(#growth-blur6)',0.9), headG);\n    const ptclG = g('growth-ptclG');\n    art.insertBefore(useEl('growth-ptclG','url(#growth-blur16)',0.9), ptclG);\n\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const bars = Array.from({length:36}, (_,i)=>({ x: 20+i/35*360, trend: Math.pow(i/35,1.3), phase: rnd(0,Math.PI*2) }));\n    const ptcls = Array.from({length:40}, ()=>({ t0: rnd(0,4), life: rnd(2,4), x: rnd(200,380) }));\n\n    function draw(t){\n      clear(barG);\n      bars.forEach(b=>{\n        const h = (30+b.trend*110) + Math.sin(t*4+b.phase)*(8+b.trend*14);\n        path(barG, seg(b.x, DH-40, b.x, DH-40-h), {stroke: hexA(pal(1),0.55), 'stroke-width':1.2, 'stroke-linecap':'round'});\n      });\n\n      const pts=[];\n      for (let x=0;x<=DW;x+=3){\n        const k = x/DW;\n        pts.push([x, (DH-50)-Math.pow(k,1.4)*130+Math.sin(x*0.05-t*2)*(8+k*12)+Math.sin(x*0.12+t*1.4)*4]);\n      }\n      clear(curveG);\n      path(curveG, smooth(pts), {stroke: pal(1), 'stroke-width':1.8});\n      shiftPath.setAttribute('d', smooth(pts.map(p=>[p[0],p[1]-1])));\n\n      clear(headG);\n      const head = pts[pts.length-8];\n      if (head) circleEl(headG, head[0], head[1]-1, 3+Math.sin(t*4), {fill: pal(0)});\n\n      clear(ptclG);\n      ptcls.forEach(p=>{\n        const local = (((t+p.t0)%p.life)+p.life)%p.life / p.life;\n        const baseY = (DH-50) - Math.pow(p.x/DW,1.4)*130;\n        circleEl(ptclG, p.x+Math.sin(t*2+p.t0)*3, baseY-local*50, 1.0,\n          {fill: hexA(pal(0), Math.max(0,Math.sin(local*Math.PI)*0.8))});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "nostalgic": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"懐古リスナー\">\n  <defs>\n    <clipPath id=\"nost-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"nost-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"nost-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"nost-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#FFB55C\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"nost-glow\">\n      <stop offset=\"0%\" stop-color=\"#FFB55C\" stop-opacity=\"0\"/>\n      <stop offset=\"40%\" stop-color=\"#FFB55C\" stop-opacity=\"0.18\"/>\n      <stop offset=\"100%\" stop-color=\"#FFB55C\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"nost-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#FFB55C\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#FFB55C\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#nost-shadow)\">\n    <g clip-path=\"url(#nost-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#nost-neonTint)\"/>\n      <g id=\"nost-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('nost-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n    function smooth(pts){\n      if (pts.length<2) return '';\n      let d = `M${pts[0][0]} ${pts[0][1]}`;\n      for (let i=0;i<pts.length-1;i++){ const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2; d += ` Q${pts[i][0]} ${pts[i][1]} ${mx} ${my}`; }\n      d += ` L${pts[pts.length-1][0]} ${pts[pts.length-1][1]}`;\n      return d;\n    }\n\n    const PAL = [\"#FFDFA8\",\"#FFB55C\",\"#E07A1A\"];\n    function pal(i){ const n=PAL.length; return PAL[((i%n)+n)%n]; }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const cx=200, cy=170;\n    const bgGlow = document.createElementNS(NS,'circle');\n    bgGlow.setAttribute('cx',cx); bgGlow.setAttribute('cy',cy); bgGlow.setAttribute('r',150);\n    bgGlow.setAttribute('fill','url(#nost-glow)');\n    art.appendChild(bgGlow);\n\n    const layers = [\n      {amp:38, freq:0.04, ci:2, w:1.4, op:0.75, speed:1.0, phase:0, hi:false},\n      {amp:30, freq:0.05, ci:1, w:1.6, op:0.95, speed:1.3, phase:1, hi:true},\n      {amp:22, freq:0.07, ci:0, w:1.2, op:0.7,  speed:1.7, phase:2, hi:false},\n      {amp:14, freq:0.10, ci:0, w:0.9, op:0.55, speed:2.1, phase:3, hi:false},\n    ];\n    const layerGs = layers.map((L,i)=>{\n      const gr = g('nost-layerG'+i);\n      art.insertBefore(useEl('nost-layerG'+i, L.hi ? 'url(#nost-blur28)' : 'url(#nost-blur16)', 0.9), gr);\n      return gr;\n    });\n    const ptclG = g('nost-ptclG');\n    art.insertBefore(useEl('nost-ptclG','url(#nost-blur16)',0.9), ptclG);\n\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const ptcls = Array.from({length:35}, ()=>({ x0: rnd(0,400), y0: rnd(40,270), phase: rnd(0,Math.PI*2) }));\n\n    function draw(t){\n      layers.forEach((L,i)=>{\n        const pts=[];\n        for (let x=-10;x<=DW+10;x+=4){\n          const env = 1-Math.abs((x-cx)/cx)*0.7;\n          pts.push([x, cy+Math.sin(x*L.freq-t*L.speed)*L.amp*env+Math.sin(x*L.freq*1.8+t*L.speed*0.6)*L.amp*0.3*env]);\n        }\n        clear(layerGs[i]);\n        path(layerGs[i], smooth(pts), {stroke: hexA(pal(L.ci), L.op), 'stroke-width':L.w, 'stroke-linecap':'round'});\n      });\n\n      clear(ptclG);\n      ptcls.forEach(p=>{\n        circleEl(ptclG, p.x0+Math.sin(t*0.6+p.phase)*8, p.y0+Math.cos(t*0.5+p.phase)*5, 0.9,\n          {fill: hexA(pal(0), 0.3+Math.abs(Math.sin(t+p.phase))*0.45)});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "genre-addict": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"ジャンル偏愛家\">\n  <defs>\n    <clipPath id=\"genre-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"genre-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"genre-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"genre-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#F5D140\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"genre-glow\">\n      <stop offset=\"0%\" stop-color=\"#F5D040\" stop-opacity=\"0\"/>\n      <stop offset=\"40%\" stop-color=\"#F5D040\" stop-opacity=\"0.18\"/>\n      <stop offset=\"100%\" stop-color=\"#F5D040\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"genre-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#F5D140\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#F5D140\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#genre-shadow)\">\n    <g clip-path=\"url(#genre-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#genre-neonTint)\"/>\n      <g id=\"genre-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('genre-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function seg(x1,y1,x2,y2){ return `M${x1} ${y1} L${x2} ${y2}`; }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n    function smooth(pts){\n      if (pts.length<2) return '';\n      let d = `M${pts[0][0]} ${pts[0][1]}`;\n      for (let i=0;i<pts.length-1;i++){ const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2; d += ` Q${pts[i][0]} ${pts[i][1]} ${mx} ${my}`; }\n      d += ` L${pts[pts.length-1][0]} ${pts[pts.length-1][1]}`;\n      return d;\n    }\n\n    const PAL = [\"#FFEFA0\",\"#F5D040\",\"#B8911C\"];\n    function pal(i){ const n=PAL.length; return PAL[((i%n)+n)%n]; }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const cx=200, cy=170;\n    const bgGlow = document.createElementNS(NS,'circle');\n    bgGlow.setAttribute('cx',cx); bgGlow.setAttribute('cy',cy); bgGlow.setAttribute('r',160);\n    bgGlow.setAttribute('fill','url(#genre-glow)');\n    art.appendChild(bgGlow);\n    const baseline = document.createElementNS(NS,'path');\n    baseline.setAttribute('d', seg(0,cy,DW,cy)); baseline.setAttribute('stroke', hexA(pal(1),0.2)); baseline.setAttribute('stroke-width',0.5);\n    art.appendChild(baseline);\n\n    const strandG = g('genre-strandG');\n    art.insertBefore(useEl('genre-strandG','url(#genre-blur16)',0.9), strandG);\n    const upG = g('genre-upG');\n    art.insertBefore(useEl('genre-upG','url(#genre-blur28)',0.9), upG);\n    const upShift = document.createElementNS(NS,'path');\n    upShift.setAttribute('fill','none'); upShift.setAttribute('stroke', hexA(pal(0),0.8)); upShift.setAttribute('stroke-width',0.7);\n    art.appendChild(upShift);\n    const dnG = g('genre-dnG');\n    art.insertBefore(useEl('genre-dnG','url(#genre-blur16)',0.9), dnG);\n\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const strands = Array.from({length:130}, (_,i)=>({ x: 10+i/129*380, phase: rnd(0,Math.PI*2) }));\n\n    function draw(t){\n      clear(strandG);\n      strands.forEach(s=>{\n        const env = Math.exp(-Math.pow((s.x-cx)/cx,2)*3.5);\n        const h = env*(4+Math.abs(Math.sin(s.x*0.3+t*7+s.phase))*38);\n        path(strandG, seg(s.x, cy-h, s.x, cy+h*0.6), {stroke: hexA(pal(1), 0.4+env*0.5), 'stroke-width':0.9, 'stroke-linecap':'round'});\n      });\n\n      const up=[], dn=[];\n      for (let x=0;x<=DW;x+=2){\n        const env = Math.exp(-Math.pow((x-cx)/cx,2)*2.5);\n        up.push([x, cy - env*(10+Math.sin(x*0.45-t*9)*20)]);\n        dn.push([x, cy + env*(8+Math.sin(x*0.35-t*7)*12)]);\n      }\n      clear(upG);\n      path(upG, smooth(up), {stroke: pal(1), 'stroke-width':1.4, 'stroke-linecap':'round'});\n      upShift.setAttribute('d', smooth(up.map(p=>[p[0],p[1]-0.5])));\n      clear(dnG);\n      path(dnG, smooth(dn), {stroke: hexA(pal(2),0.55), 'stroke-width':1.1});\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "balanced": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"バランス型\">\n  <defs>\n    <clipPath id=\"bal-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"bal-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#9E6BFF\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"bal-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#9E6BFF\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#9E6BFF\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#bal-shadow)\">\n    <g clip-path=\"url(#bal-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#bal-neonTint)\"/>\n      <g id=\"bal-art\" style=\"mix-blend-mode:screen\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const art = svg.getElementById('bal-art');\n\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function catmullRomClosed(pts){\n      const n = pts.length; if (n<2) return '';\n      let d = `M${pts[0][0]} ${pts[0][1]}`;\n      for (let i=0;i<n;i++){\n        const p0=pts[(i-1+n)%n], p1=pts[i], p2=pts[(i+1)%n], p3=pts[(i+2)%n];\n        const c1x=p1[0]+(p2[0]-p0[0])/6, c1y=p1[1]+(p2[1]-p0[1])/6;\n        const c2x=p2[0]-(p3[0]-p1[0])/6, c2y=p2[1]-(p3[1]-p1[1])/6;\n        d += ` C${c1x} ${c1y} ${c2x} ${c2y} ${p2[0]} ${p2[1]}`;\n      }\n      return d + ' Z';\n    }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const half = 120, cx = half, cy = half, s = 240/400, lw = s*2.0;\n    const rings = [\n      {r: half*0.78, col:'#FF5478', dir: 1, seed:0},\n      {r: half*0.61, col:'#FFAB33', dir:-1, seed:8},\n      {r: half*0.44, col:'#66FF99', dir: 1, seed:16},\n      {r: half*0.28, col:'#45ABFF', dir:-1, seed:24},\n      {r: half*0.13, col:'#AB66FF', dir: 1, seed:32},\n    ];\n    const maxAmp = half*0.07;\n\n    function organicRingPath(baseR, detPh, jitPh, scale, rot, dir, segs){\n      const pts = [];\n      for (let n=0;n<segs;n++){\n        const a = n/segs*Math.PI*2;\n        const det = Math.sin(a*6+detPh)*0.7;\n        const jit = Math.sin(a*12+jitPh)*0.1;\n        const r = baseR + (det+jit)*maxAmp*scale*dir;\n        const fa = a+rot;\n        pts.push([cx+r*Math.cos(fa), cy+r*Math.sin(fa)]);\n      }\n      return catmullRomClosed(pts);\n    }\n\n    function draw(t){\n      clear(art);\n      rings.forEach(ring=>{\n        const speedBase = 0.30 + ring.r/half*0.10;\n        for (let i=0;i<8;i++){\n          const f = i+ring.seed;\n          const ph = f*Math.PI*1.6180339887;\n          const spd = speedBase + (f%7)*0.09;\n          const v0 = 0.28 + (f%5)*0.13;\n          const v1 = 0.52 + (f%7)*0.08;\n          const v2 = 0.81 + (f%4)*0.08;\n          const ds = (Math.sin(t*v0+f*1.10)+Math.sin(t*v1+f*2.30)+Math.sin(t*v2+f*3.70))/3;\n          const scl = (ds+1)*0.5;\n          const rotSpd = ((f%11)-5.0)/5.0*0.048;\n          const detPh = t*spd+ph;\n          const jitPh = -(t*spd*0.8)+ph*1.3;\n          const d = organicRingPath(ring.r, detPh, jitPh, scl, t*rotSpd, ring.dir, 20);\n          path(art, d, {stroke: hexA(ring.col, 0.40), 'stroke-width': lw});\n        }\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "collector": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"コレクター(CD)\">\n  <defs>\n    <clipPath id=\"coll-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"></circle></clipPath>\n    <filter id=\"coll-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"></feGaussianBlur></filter>\n    <filter id=\"coll-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"></feGaussianBlur></filter>\n    <filter id=\"coll-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#FFFFFF\" flood-opacity=\"0.6\"></feDropShadow>\n    </filter>\n    <radialGradient id=\"coll-glow\">\n      <stop offset=\"0%\" stop-color=\"#C168FF\" stop-opacity=\"0\"></stop>\n      <stop offset=\"40%\" stop-color=\"#C168FF\" stop-opacity=\"0.08\"></stop>\n      <stop offset=\"100%\" stop-color=\"#C168FF\" stop-opacity=\"0\"></stop>\n    </radialGradient>\n    <radialGradient id=\"coll-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#C269FF\" stop-opacity=\"0.10\"></stop>\n      <stop offset=\"100%\" stop-color=\"#C269FF\" stop-opacity=\"0\"></stop>\n    </radialGradient>\n    <linearGradient id=\"coll-rainbowGrad\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n      <stop offset=\"0%\" stop-color=\"#FFFFFF\" stop-opacity=\"0\"></stop>\n      <stop offset=\"14%\" stop-color=\"#FF5C5C\" stop-opacity=\"0.55\"></stop>\n      <stop offset=\"30%\" stop-color=\"#FFC24B\" stop-opacity=\"0.5\"></stop>\n      <stop offset=\"46%\" stop-color=\"#F5F06B\" stop-opacity=\"0.45\"></stop>\n      <stop offset=\"62%\" stop-color=\"#6BE6A6\" stop-opacity=\"0.5\"></stop>\n      <stop offset=\"78%\" stop-color=\"#5CB8FF\" stop-opacity=\"0.5\"></stop>\n      <stop offset=\"92%\" stop-color=\"#C48CFF\" stop-opacity=\"0.5\"></stop>\n      <stop offset=\"100%\" stop-color=\"#FFFFFF\" stop-opacity=\"0\"></stop>\n    </linearGradient>\n  </defs>\n  <g filter=\"url(#coll-shadow)\">\n    <g clip-path=\"url(#coll-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#6E6F76\"></circle>\n      <g id=\"coll-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('coll-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function seg(x1,y1,x2,y2){ return `M${x1} ${y1} L${x2} ${y2}`; }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n    function donutSeg(cx,cy,r1,r2,a1,a2){\n      const x1=cx+Math.cos(a1)*r1, y1=cy+Math.sin(a1)*r1, x2=cx+Math.cos(a2)*r1, y2=cy+Math.sin(a2)*r1;\n      const x3=cx+Math.cos(a2)*r2, y3=cy+Math.sin(a2)*r2, x4=cx+Math.cos(a1)*r2, y4=cy+Math.sin(a1)*r2;\n      const large = (a2-a1)>Math.PI ? 1 : 0;\n      return `M${x1} ${y1} A${r1} ${r1} 0 ${large} 1 ${x2} ${y2} L${x3} ${y3} A${r2} ${r2} 0 ${large} 0 ${x4} ${y4} Z`;\n    }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const SILVER_LIGHT = '#FAFBFD', SILVER_MID = '#DADEE6', SILVER_DARK = '#26272C';\n    const BRAND = '#C168FF';\n\n    const cx=200, cy=165;\n\n\n    const backG = g('coll-backG');\n    art.insertBefore(useEl('coll-backG','url(#coll-blur28)',0.9), backG);\n    const backDiscs = [ {dx:-58, dy:-14, r:74}, {dx:50, dy:22, r:64} ];\n    backDiscs.forEach(bd=>{\n      const dcx=cx+bd.dx, dcy=cy+bd.dy;\n      circleEl(backG, dcx, dcy, bd.r, {fill:'none', stroke: hexA(SILVER_MID,0.45), 'stroke-width':1.1});\n      circleEl(backG, dcx, dcy, bd.r*0.55, {fill:'none', stroke: hexA(SILVER_DARK,0.4), 'stroke-width':0.6});\n      circleEl(backG, dcx, dcy, bd.r*0.14, {fill:'#15151A', stroke: hexA(SILVER_MID,0.45), 'stroke-width':0.6});\n    });\n\n    const R = 96;\n    const frontSpinG = g('coll-frontSpinG');\n    circleEl(frontSpinG, cx, cy, R, {fill:'none', stroke: hexA(SILVER_LIGHT,0.85), 'stroke-width':1.6});\n    [0.40,0.55,0.70,0.84,0.95].forEach((f,i)=>{\n      circleEl(frontSpinG, cx, cy, R*f, {fill:'none', stroke: hexA(i%2? SILVER_DARK:SILVER_MID, 0.55), 'stroke-width':0.6});\n    });\n    path(frontSpinG, donutSeg(cx,cy, R*0.32, R*0.97, -0.55, 0.35), {fill:'url(#coll-rainbowGrad)', stroke:'none', 'style':'mix-blend-mode:screen'});\n    path(frontSpinG, seg(cx+Math.cos(0)*R*0.86, cy+Math.sin(0)*R*0.86, cx+Math.cos(0)*R*0.98, cy+Math.sin(0)*R*0.98),\n      {stroke: hexA(SILVER_LIGHT,0.9), 'stroke-width':1.4, 'stroke-linecap':'round'});\n    art.insertBefore(useEl('coll-frontSpinG','url(#coll-blur16)',0.35), frontSpinG);\n\n    const hubG = g('coll-hubG');\n    circleEl(hubG, cx, cy, R*0.16, {fill:'#15151A', stroke: hexA(SILVER_LIGHT,0.7), 'stroke-width':0.9});\n    circleEl(hubG, cx, cy, R*0.065, {fill:'none', stroke: hexA(SILVER_MID,0.6), 'stroke-width':0.5});\n\n    const glint = document.createElementNS(NS,'ellipse');\n    glint.setAttribute('cx', cx-R*0.32); glint.setAttribute('cy', cy-R*0.4);\n    glint.setAttribute('rx', R*0.28); glint.setAttribute('ry', R*0.14);\n    glint.setAttribute('fill', hexA(SILVER_LIGHT,0.16));\n    glint.setAttribute('filter','url(#coll-blur16)');\n    art.appendChild(glint);\n\n    const ptclG = g('coll-ptclG');\n    art.insertBefore(useEl('coll-ptclG','url(#coll-blur16)',0.9), ptclG);\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const ptcls = Array.from({length:14}, ()=>({ x: cx+rnd(-150,150), y: cy+rnd(-115,115), phase: rnd(0,Math.PI*2), r: rnd(1.0,1.6), brand: Math.random()<0.35 }));\n\n    function draw(t){\n      frontSpinG.setAttribute('transform', `rotate(${(t*16)%360} ${cx} ${cy})`);\n\n      clear(ptclG);\n      ptcls.forEach(p=>{\n        const px = p.x+Math.sin(t*0.7+p.phase)*5, py = p.y+Math.cos(t*0.6+p.phase)*5;\n        circleEl(ptclG, px, py, p.r+0.6, {fill: 'rgba(10,10,14,0.55)'});\n        circleEl(ptclG, px, py, p.r,\n          {fill: hexA(p.brand?BRAND:SILVER_LIGHT, 0.55+Math.abs(Math.sin(t*1.1+p.phase))*0.4)});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
  "streaming-fan": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 240 240\" width=\"240\" height=\"240\" role=\"img\" aria-label=\"サブスク派\">\n  <defs>\n    <clipPath id=\"sub-clip\"><circle cx=\"120\" cy=\"120\" r=\"104\"/></clipPath>\n    <filter id=\"sub-blur16\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"1.6\"/></filter>\n    <filter id=\"sub-blur28\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\"><feGaussianBlur stdDeviation=\"2.8\"/></filter>\n    <filter id=\"sub-blur6\" x=\"-100%\" y=\"-100%\" width=\"300%\" height=\"300%\"><feGaussianBlur stdDeviation=\"6\"/></filter>\n    <filter id=\"sub-shadow\" x=\"-60%\" y=\"-60%\" width=\"220%\" height=\"220%\">\n      <feDropShadow dx=\"0\" dy=\"0\" stdDeviation=\"6\" flood-color=\"#FA243D\" flood-opacity=\"0.6\"/>\n    </filter>\n    <radialGradient id=\"sub-glow\">\n      <stop offset=\"0%\" stop-color=\"#FA243C\" stop-opacity=\"0\"/>\n      <stop offset=\"40%\" stop-color=\"#FA243C\" stop-opacity=\"0.18\"/>\n      <stop offset=\"100%\" stop-color=\"#FA243C\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <radialGradient id=\"sub-neonTint\">\n      <stop offset=\"0%\" stop-color=\"#FA243D\" stop-opacity=\"0.22\"/>\n      <stop offset=\"100%\" stop-color=\"#FA243D\" stop-opacity=\"0\"/>\n    </radialGradient>\n  </defs>\n  <g filter=\"url(#sub-shadow)\">\n    <g clip-path=\"url(#sub-clip)\">\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"#000\"/>\n      <circle cx=\"120\" cy=\"120\" r=\"104\" fill=\"url(#sub-neonTint)\"/>\n      <g id=\"sub-art\"></g>\n    </g>\n  </g>\n  <script><![CDATA[\n  (function(){\n    const svg = document.currentScript.parentNode;\n    const NS = \"http://www.w3.org/2000/svg\";\n    const DW = 400, DH = 310, SC = 240/DH, TX = (240 - DW*SC)/2, TY = (240 - DH*SC)/2;\n    const art = svg.getElementById('sub-art');\n    art.setAttribute('transform', `translate(${TX} ${TY}) scale(${SC})`);\n\n    function g(id){ const e=document.createElementNS(NS,'g'); if(id)e.setAttribute('id',id); art.appendChild(e); return e; }\n    function clear(node){ while(node.firstChild) node.removeChild(node.firstChild); }\n    function path(parent, d, attrs){ const e=document.createElementNS(NS,'path'); e.setAttribute('d',d); e.setAttribute('fill','none'); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function circleEl(parent, cx, cy, r, attrs){ const e=document.createElementNS(NS,'circle'); e.setAttribute('cx',cx); e.setAttribute('cy',cy); e.setAttribute('r',Math.max(0,r)); for(const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); }\n    function useEl(id, filter, opacity){ const u=document.createElementNS(NS,'use'); u.setAttribute('href','#'+id); if(filter) u.setAttribute('filter',filter); if(opacity!=null) u.setAttribute('opacity',opacity); return u; }\n    function smooth(pts){\n      if (pts.length<2) return '';\n      let d = `M${pts[0][0]} ${pts[0][1]}`;\n      for (let i=0;i<pts.length-1;i++){ const mx=(pts[i][0]+pts[i+1][0])/2, my=(pts[i][1]+pts[i+1][1])/2; d += ` Q${pts[i][0]} ${pts[i][1]} ${mx} ${my}`; }\n      d += ` L${pts[pts.length-1][0]} ${pts[pts.length-1][1]}`;\n      return d;\n    }\n    function hexA(hex, a){ const v=parseInt(hex.replace('#',''),16); return `rgba(${(v>>16)&255},${(v>>8)&255},${v&255},${a})`; }\n\n    const cx=200, cy=165;\n    const bgGlow = document.createElementNS(NS,'circle');\n    bgGlow.setAttribute('cx',cx); bgGlow.setAttribute('cy',cy); bgGlow.setAttribute('r',160);\n    bgGlow.setAttribute('fill','url(#sub-glow)');\n    art.appendChild(bgGlow);\n\n    const layers = [\n      {hex:'#A06BFF', w:1.2, amp:36, offset:0.0, speed:1.25, op:0.55},\n      {hex:'#FA243C', w:2.0, amp:32, offset:0.8, speed:0.95, op:1.00},\n      {hex:'#FF7AA3', w:1.5, amp:34, offset:0.4, speed:1.10, op:0.85},\n      {hex:'#48C4FF', w:1.0, amp:30, offset:1.6, speed:1.40, op:0.55},\n    ];\n    const haloGs = [], mainGs = [];\n    layers.forEach((L,i)=>{\n      const halo = g('sub-haloG'+i);\n      art.insertBefore(useEl('sub-haloG'+i,'url(#sub-blur6)',0.9), halo);\n      haloGs.push(halo);\n    });\n    layers.forEach((L,i)=>{\n      const main = g('sub-mainG'+i);\n      art.insertBefore(useEl('sub-mainG'+i,'url(#sub-blur28)',0.9), main);\n      mainGs.push(main);\n    });\n    const ptclG = g('sub-ptclG');\n    art.insertBefore(useEl('sub-ptclG','url(#sub-blur16)',0.9), ptclG);\n\n    const rnd = (a,b)=>a+Math.random()*(b-a);\n    const ptcls = Array.from({length:80}, ()=>({ layer: Math.floor(rnd(0,4)), t0: rnd(0,4) }));\n\n    function waveXY(x, t, L){\n      const env = 1-Math.abs((x-cx)/cx)*0.4;\n      const w1 = Math.sin(x*0.025 - t*L.speed + L.offset) * L.amp * env;\n      const w2 = Math.sin(x*0.05  + t*L.speed*0.7 + L.offset) * L.amp * 0.4 * env;\n      return cy + w1 + w2;\n    }\n\n    function draw(t){\n      const allPts = layers.map(L=>{\n        const pts=[];\n        for (let x=-10;x<=DW+10;x+=4) pts.push([x, waveXY(x,t,L)]);\n        return pts;\n      });\n      layers.forEach((L,i)=>{\n        const d = smooth(allPts[i]);\n        clear(haloGs[i]);\n        path(haloGs[i], d, {stroke: hexA(L.hex,0.25), 'stroke-width': L.w+1});\n        clear(mainGs[i]);\n        path(mainGs[i], d, {stroke: hexA(L.hex,L.op), 'stroke-width': L.w, 'stroke-linecap':'round'});\n      });\n\n      clear(ptclG);\n      ptcls.forEach(p=>{\n        const L = layers[p.layer];\n        const local = (((t*0.15+p.t0)%1)+1)%1;\n        const x = local*DW;\n        const y = waveXY(x,t,L);\n        circleEl(ptclG, x, y, 1.1, {fill: hexA(L.hex, Math.max(0,Math.sin(local*Math.PI)*0.85))});\n      });\n    }\n\n    const start = performance.now();\n    function frame(now){ draw((now-start)/1000); requestAnimationFrame(frame); }\n    requestAnimationFrame(frame);\n  })();\n  ]]></script>\n</svg>",
};
